import { createHash } from "node:crypto";
export default function ({ body }) {
  if (!body || !Array.isArray(body.data)) throw Error("Expected JSON object with data array");
  const chunks = [];
  for (const d of body.data) {
    if (
      !d ||
      typeof d.id !== "string" ||
      typeof d.description !== "string" ||
      !d.description.trim()
    )
      throw Error("Each MITRE document requires id and description");
    for (let start = 0, index = 0; start < d.description.length; start += 2700, index++) {
      const content = d.description.slice(start, start + 3000);
      const h = createHash("sha256")
          .update(d.id + ":" + index)
          .digest("hex")
          .slice(0, 32),
        id =
          h.slice(0, 8) +
          "-" +
          h.slice(8, 12) +
          "-4" +
          h.slice(13, 16) +
          "-a" +
          h.slice(17, 20) +
          "-" +
          h.slice(20);
      chunks.push({
        id,
        content,
        metadata: {
          id: d.id,
          name: d.name ?? "",
          killchain: d.kill_chain_phases ?? [],
          external: d.external_references ?? [],
        },
      });
      if (start + 3000 >= d.description.length) break;
    }
  }
  return { chunks };
}

