export default function ({ chunks, previous }) {
  const i = (previous?.i ?? -1) + 1,
    c = chunks[i];
  if (!c)
    return {
      state: { i },
      more: false,
      chunk: { id: "00000000-0000-4000-a000-000000000000", content: "", metadata: {} },
    };
  return { state: { i }, more: true, chunk: c };
}

