export default function ({ response, chunk }) {
  const v = response?.data?.[0]?.embedding;
  if (
    !Array.isArray(v) ||
    v.length !== 1536 ||
    v.some((x) => typeof x !== "number" || !Number.isFinite(x))
  )
    throw Error("Invalid embedding");
  return {
    points: [
      { id: chunk.id, vector: v, payload: { content: chunk.content, metadata: chunk.metadata } },
    ],
  };
}

